run() { docker cp $1 filenest-app:/tmp/x.php; docker exec -u www-data -w /var/www/html filenest-app php -r "require 'vendor/autoload.php'; \$app = require 'bootstrap/app.php'; \$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); require '/tmp/x.php';" 2>&1 | tail -12; docker exec filenest-app rm -f /tmp/x.php; }
echo '' | base64 -d > /tmp/kt2.php; echo '' | base64 -d > /tmp/kt3.php
run /tmp/kt2.php
BC=$(docker exec filenest-app sh -c 'cd /var/www/html && php -r "\$i=json_decode(file_get_contents(\"/tmp/kt-ids\"),true); echo \$i[\"copy\"];"')
BARCODE=$(docker exec filenest-db sh -c 'mysql -N -u root -p"$MYSQL_ROOT_PASSWORD" filenest -e "select barcode from book_copies where id='$BC'"' 2>/dev/null)
echo "Koha desk returns $BARCODE"
docker exec koha-test koha-shell kohadent -c "perl -MC4::Context -MC4::Circulation -e 'my @r = C4::Circulation::AddReturn(q{$BARCODE}, q{DENT}); print qq{koha AddReturn: $r[0]\n}'"
docker exec koha-test koha-mysql kohadent -e "select borrowernumber, cardnumber, surname, categorycode from borrowers where cardnumber='KTEST1'; select count(*) open_issues from issues; select count(*) holds from reserves;"
sleep 25
run /tmp/kt3.php
docker exec koha-test koha-mysql kohadent -e "select count(*) biblios from biblio; select biblionumber, title from biblio order by biblionumber desc limit 1;"
rm -f /tmp/kt2.php /tmp/kt3.php
